import { MeshStandardNodeMaterial, MeshPhysicalNodeMaterial } from 'three/webgpu';
import { texture, uv, positionLocal, vec3, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, OctahedronGeometry, PointLight, Color } = ctx.THREE;

  // Root container
  const container = new Group();

  // Create local states/timelines to dispose later
  const timelines = [];
  const texturesToDispose = [];

  // 1. STAGE BACKDROP (avoiding FLAT_VOID, carrying spec gradient)
  const bgGeom = new PlaneGeometry(8, 6);
  const bgMat = new MeshStandardNodeMaterial({
    roughness: 0.8,
    metalness: 0.1,
  });

  // Custom gradient via TSL using spec colors
  // ink: #16161d, surface: #0b0b10, accent: #ff2a38 (as subtle glow)
  const uColorInk = uniform(new Color('#16161d'));
  const uColorSurface = uniform(new Color('#0b0b10'));
  const gradient = uv().y.mix(uColorSurface, uColorInk);
  bgMat.colorNode = gradient;

  const backdrop = new Mesh(bgGeom, bgMat);
  backdrop.position.z = -2.0;
  container.add(backdrop);

  // 2. MAIN DIVIDER GROUP (for mouse relative parallax and hover lift)
  const dividerGroup = new Group();
  container.add(dividerGroup);

  // 3. MACHINED RULE WITH TS DISPLACEMENT
  const dividerHeight = 0.8;
  const dividerWidth = 5.0;
  const ruleGeom = new PlaneGeometry(dividerWidth, dividerHeight, 64, 16);

  // Displacement / texture uniforms
  const dispScaleUniform = uniform(0.12);
  const ruleMat = new MeshStandardNodeMaterial({
    roughness: 0.35,
    metalness: 0.85,
    flatShading: true,
  });

  // Load physical rule textures
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      ruleMat.colorNode = texture(tex);
      texturesToDispose.push(tex);
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      const depthNode = texture(depthTex);
      ruleMat.positionNode = positionLocal.add(vec3(0, 0, depthNode.r.mul(dispScaleUniform)));
      texturesToDispose.push(depthTex);
    });
  }

  const ruleMesh = new Mesh(ruleGeom, ruleMat);
  dividerGroup.add(ruleMesh);

  // 4. CENTER JEWEL (Glossy Physical Diamond Mesh for high-end feel)
  const jewelGeom = new OctahedronGeometry(0.18, 0);
  const jewelMat = new MeshPhysicalNodeMaterial({
    color: new Color('#ff2a38'), // Accent Color
    roughness: 0.05,
    metalness: 0.1,
    transmission: 1.0,
    thickness: 0.8,
    ior: 1.6,
    clearcoat: 1.0,
    emissive: new Color('#ff2a38'),
  });

  // Animate jewel emissive mapping slightly for extra glimmer
  const emissiveInten = uniform(0.85);
  jewelMat.emissiveNode = vec3(emissiveInten.mul(uniform(new Color('#ff2a38'))));

  const jewelMesh = new Mesh(jewelGeom, jewelMat);
  jewelMesh.position.set(0, 0, 0.15);
  dividerGroup.add(jewelMesh);

  // Glow interaction timeline
  const glimmerTl = gsap.to(emissiveInten, {
    value: 1.6,
    duration: 2.0,
    repeat: -1,
    yoyo: true,
    ease: 'sine.inOut'
  });
  timelines.push(glimmerTl);

  // 5. LOCAL POINT LIGHTING (Rim/Atmospheric Accent Glow)
  const rimLight = new PointLight('#ff2a38', 1.8, 4.0);
  rimLight.position.set(0, 0.2, 0.5);
  dividerGroup.add(rimLight);

  // 6. INTERACTION & HANDLERS
  const handlers = {
    pointermove: (e) => {
      if (e.point) {
        // Subtle tilt parallax
        gsap.to(dividerGroup.rotation, {
          x: -e.point.y * 0.12,
          y: e.point.x * 0.08,
          duration: 0.4,
          ease: 'power2.out'
        });
      }
    },
    pointerover: () => {
      // "hover lift (rise-in) - 0.15 scene units"
      gsap.to(dividerGroup.position, {
        z: 0.15,
        duration: 0.5,
        ease: 'power3.out'
      });
      // Brighten jewel on hover
      gsap.to(emissiveInten, {
        value: 2.2,
        duration: 0.3,
        ease: 'power2.out'
      });
    },
    pointerout: () => {
      // Revert positioning
      gsap.to(dividerGroup.position, {
        z: 0,
        duration: 0.5,
        ease: 'power3.out'
      });
      gsap.to(dividerGroup.rotation, {
        x: 0,
        y: 0,
        duration: 0.5,
        ease: 'power2.out'
      });
      gsap.to(emissiveInten, {
        value: 0.85,
        duration: 0.5,
        ease: 'power2.out'
      });
    },
    click: () => {
      // "press-down on click" scale effect
      const clickTl = gsap.timeline()
        .to(dividerGroup.scale, { x: 0.96, y: 0.96, z: 0.96, duration: 0.12, ease: 'power2.out' })
        .to(dividerGroup.scale, { x: 1.0, y: 1.0, z: 1.0, duration: 0.4, ease: 'power4.out' });
      timelines.push(clickTl);

      // Emit event
      ctx.emit('hub-features.select', {});
    }
  };

  container.userData.handlers = handlers;

  // 7. CLEANUP
  container.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    texturesToDispose.forEach((tex) => tex.dispose());
    bgGeom.dispose();
    bgMat.dispose();
    ruleGeom.dispose();
    ruleMat.dispose();
    jewelGeom.dispose();
    jewelMat.dispose();
  };

  // Applying primitives from cinematicPrimitives configurations if any
  const primList = config.cinematicPrimitives ?? [];
  primList.forEach((prim) => {
    if (ctx.primitives[prim.name]) {
      const res = ctx.primitives[prim.name](dividerGroup, prim.params);
      if (res) {
        if (res.timeline) timelines.push(res.timeline);
        if (res.cleanup) {
          const oldCleanup = container.userData.cleanup;
          container.userData.cleanup = () => {
            oldCleanup();
            res.cleanup();
          };
        }
      }
    }
  });

  return container;
}
